import threading, json, urllib.error, importlib, sys, time
from http.server import BaseHTTPRequestHandler, HTTPServer
sys.path.insert(0, '.')
import weather; importlib.reload(weather)

def serve(fail_n, code=503):
    state = {'n': 0}
    class H(BaseHTTPRequestHandler):
        def do_GET(self):
            state['n'] += 1
            if state['n'] <= fail_n:
                self.send_response(code); self.end_headers(); return
            self.send_response(200); self.end_headers(); self.wfile.write(b'{"t":1}')
        def log_message(self, *a): pass
    s = HTTPServer(('127.0.0.1', 0), H)
    threading.Thread(target=s.serve_forever, daemon=True).start()
    return s, state

for fail_n, code in [(2, 503), (99, 503), (5, 404)]:
    s, st = serve(fail_n, code)
    c = weather.WeatherClient(f"http://127.0.0.1:{s.server_port}", backoff=0.01)
    try: r = c.get("x")
    except urllib.error.HTTPError as e: r = f"HTTPError {e.code}"
    print(fail_n, code, r, "requests:", st['n'])
    s.shutdown()

